"""Reviewed corrections to the supplied papers, applied after lossless text extraction.

Numbers refer to each source paper, before the combined test is numbered 1–200.
"""


def correct_bank(bank):
    changes = []
    lookup = {(q['section'], int(q['id'].rsplit('-', 1)[1])): q for q in bank}

    def fix(section, n, reason, en, te, answer=None, option=None, text=None):
        q = lookup[section, n]
        if answer is not None:
            q['correct'] = answer
        if option:
            index, english, telugu = option
            q['options']['en'][index] = english
            q['options']['te'][index] = telugu
        if text:
            q['text'] = dict(zip(('en', 'te'), text))
        q['explanation'] = {'en': en, 'te': te}
        changes.append((section, n, reason))
        return q

    def ar(n, reason, en, te, **kwargs):
        return fix('arithmetic', n, reason, en, te, **kwargs)

    ar(2, 'Missing correct option: 29:20.', 'Use x:y:z = 10:14:15. The required ratio is (30 + 28):(70 − 30) = 58:40 = 29:20.', 'x:y:z = 10:14:15. కావలసిన నిష్పత్తి (30 + 28):(70 − 30) = 58:40 = 29:20.', option=(2, '29:20', '29:20'))
    ar(4, 'The old solution answered a+b+c, not the expression asked.', 'Replace a, b, c by their remainders. 9² + 2×7 − 3×10 = 65, which is divisible by 13. Remainder = 0.', 'a, b, c స్థానాల్లో శేషాలను ఉంచితే 9² + 2×7 − 3×10 = 65. ఇది 13తో పూర్తిగా భాగించబడుతుంది. శేషం 0.')
    ar(6, 'Key B → A; exact recurring percentage stated.', 'Annual interest = (12,600 − 10,200)/2 = ₹1,200. Principal = 10,200 − 3×1,200 = ₹6,600. Rate = (1,200/6,600)×100 = 18 2/11% per annum.', 'ఏడాది వడ్డీ = (12,600 − 10,200)/2 = ₹1,200. అసలు = 10,200 − 3×1,200 = ₹6,600. వడ్డీ రేటు = (1,200/6,600)×100 = సంవత్సరానికి 18 2/11%.', answer=0, option=(0, '₹6,600, 18 2/11%', '₹6,600, 18 2/11%'))
    ar(7, 'Explicit brackets replace ambiguous OF/vinculum notation; key B → A.', '(3 − 1) = 2; (5 − 2) = 3; 8 ÷ 4 × 3 = 6. The square bracket is 15 − 6 = 9. Therefore 18 ÷ 6 × 9 = 27.', '(3 − 1) = 2; (5 − 2) = 3; 8 ÷ 4 × 3 = 6. పెద్ద కుండలీకరణంలో 15 − 6 = 9. అందువల్ల 18 ÷ 6 × 9 = 27.', answer=0, text=('Find the value of the expression:\n18 ÷ (3 × 2) × [15 − {8 ÷ 4 × (5 − (3 − 1))}]', 'క్రింది సమాసం విలువ కనుగొనండి:\n18 ÷ (3 × 2) × [15 − {8 ÷ 4 × (5 − (3 − 1))}]'))
    ar(8, 'Missing correct option: 7.2 days.', 'Take total work as 240 units. A, B and C work at 10, 12 and 15 units/day. A and B finish 132 units in 6 days. C needs (240 − 132)/15 = 7.2 days.', 'మొత్తం పని 240 యూనిట్లు అనుకుందాం. A, B, C రోజుకు 10, 12, 15 యూనిట్లు చేస్తారు. A, B ఆరు రోజుల్లో 132 యూనిట్లు చేస్తారు. మిగిలిన పని C పూర్తి చేయడానికి (240 − 132)/15 = 7.2 రోజులు.', option=(1, '7.2 days', '7.2 రోజులు'))
    ar(10, 'Key B → C.', 'After removal let milk and water be 7x and 3x litres. 7x/(3x+12) = 7/5 gives x = 6. Remaining mixture = 60 litres; original mixture = 60 + 20 = 80 litres.', 'తీసివేసిన తర్వాత పాలు 7x, నీరు 3x లీటర్లు అనుకుందాం. 7x/(3x+12) = 7/5 నుండి x = 6. మిగిలిన మిశ్రమం 60 లీటర్లు. మొదట ఉన్నది 60 + 20 = 80 లీటర్లు.', answer=2)
    ar(13, 'Missing correct option: 12 hours.', 'For a 96-unit tank, A and B fill 10 units/hour and C drains 3 units/hour. First 4 hours fill 40 units. The remaining 56 units take 56/7 = 8 hours. Total = 12 hours.', 'ట్యాంకు సామర్థ్యం 96 యూనిట్లు అయితే A, B గంటకు 10 యూనిట్లు నింపుతారు; C గంటకు 3 యూనిట్లు ఖాళీ చేస్తుంది. మొదటి 4 గంటల్లో 40 యూనిట్లు నిండుతాయి. మిగిలిన 56 యూనిట్లకు 56/7 = 8 గంటలు. మొత్తం 12 గంటలు.', option=(2, '12 hours', '12 గంటలు'))
    q = ar(14, 'Correct capital-time ratio is 25:21; specify rounding to paise.', 'A: 45,000×4 + 40,000×8 = 500,000 capital-months. B: 30,000×6 + 40,000×6 = 420,000. Ratio = 25:21. A receives 38,000×25/46 = ₹20,652.17, rounded to the nearest paisa.', 'A పెట్టుబడి-నెలలు = 45,000×4 + 40,000×8 = 500,000. B కి 30,000×6 + 40,000×6 = 420,000. నిష్పత్తి 25:21. A వాటా = 38,000×25/46 = సుమారు ₹20,652.17.', option=(2, '₹20,652.17', '₹20,652.17'))
    q['text']['en'] += ' Round to the nearest paisa.'
    q['text']['te'] += ' సమీప పైసాకు సవరించండి.'
    ar(15, 'Missing correct ratio: 29:14.', 'Let present ages be 9x and 4x. 2(9x−7) = 5(4x−7), so x = 10.5. Seven years later their ages are 101.5 and 49, giving 101.5:49 = 29:14.', 'ప్రస్తుత వయస్సులు 9x, 4x అనుకుందాం. 2(9x−7) = 5(4x−7) నుండి x = 10.5. ఏడు సంవత్సరాల తర్వాత వయస్సులు 101.5, 49. నిష్పత్తి 101.5:49 = 29:14.', option=(0, '29:14', '29:14'))
    ar(16, 'Missing correct option: ₹15,600.', 'Length + breadth = 66 and length − breadth = 14, so dimensions are 40 m and 26 m. Area = 1,040 m². Cost = 1,040×15 = ₹15,600.', 'పొడవు + వెడల్పు = 66; పొడవు − వెడల్పు = 14. కాబట్టి పొడవు 40 మీ., వెడల్పు 26 మీ. వైశాల్యం 1,040 చ.మీ. ఖర్చు = 1,040×15 = ₹15,600.', option=(2, '₹15,600', '₹15,600'))
    ar(24, 'Key B → A.', 'Correct total = 40×68 − 48 − 64 + 84 + 78 = 2,770. Correct average = 2,770/40 = 69.25.', 'సరైన మొత్తం = 40×68 − 48 − 64 + 84 + 78 = 2,770. సరైన సగటు = 2,770/40 = 69.25.', answer=0)
    q = ar(26, 'Second part is ₹124,800/17, not ₹7,200; specify rounding.', 'Equal interest gives 0.32P₁ = 0.36P₂, so P₁:P₂ = 9:8. The second part is 15,600×8/17 = ₹7,341.18, rounded to the nearest paisa.', 'వడ్డీలు సమానం కాబట్టి 0.32P₁ = 0.36P₂. అసళ్ల నిష్పత్తి 9:8. రెండవ భాగం = 15,600×8/17 = సుమారు ₹7,341.18.', option=(0, '₹7,341.18', '₹7,341.18'))
    q['text']['en'] += ' Round to the nearest paisa.'
    q['text']['te'] += ' సమీప పైసాకు సవరించండి.'
    ar(27, 'Key B → A.', 'Cylinder volume = π×6²×14 = 504π cm³. Each sphere has radius 1 cm and volume 4π/3 cm³. Number = 504π ÷ (4π/3) = 378.', 'స్తూపం ఘనపరిమాణం = π×6²×14 = 504π ఘ.సెం.మీ. ప్రతి గోళం వ్యాసార్థం 1 సెం.మీ.; ఘనపరిమాణం 4π/3. గోళాల సంఖ్య = 504π ÷ (4π/3) = 378.', answer=0)
    ar(28, 'Key D → B; source confused B’s time with A’s time.', 'A and B finish 12/18 = 2/3 of the work. B takes 15 days for 1/3, hence 45 days for all of it. A’s rate = 1/18 − 1/45 = 1/30. A alone needs 30 days.', 'A, B కలిసి 12/18 = 2/3 పని చేస్తారు. B మిగిలిన 1/3 పనికి 15 రోజులు తీసుకుంటాడు; మొత్తం పనికి 45 రోజులు. A పని రేటు = 1/18 − 1/45 = 1/30. కాబట్టి A ఒక్కడికి 30 రోజులు.', answer=1)
    ar(30, 'Exact decimal 0.9801 replaces unsupported rounding.', '0.081×0.484 = 0.039204 and 0.0064×6.25 = 0.04. The quotient is 0.039204/0.04 = 0.9801 exactly.', '0.081×0.484 = 0.039204; 0.0064×6.25 = 0.04. భాగఫలం = 0.039204/0.04 = 0.9801.', option=(0, '0.9801', '0.9801'))
    q = ar(32, 'Original savings imply negative expenditure; use P ₹4,000 and Q ₹5,000.', 'Let incomes be 5x, 4x and expenditures 7y, 5y. Then 5x−7y = 4,000 and 4x−5y = 5,000. Eliminating y gives 3x = 15,000, so x = 5,000 and P’s income = ₹25,000. Expenditures are ₹21,000 and ₹15,000, both positive.', 'ఆదాయాలు 5x, 4x; ఖర్చులు 7y, 5y అనుకుందాం. 5x−7y = 4,000; 4x−5y = 5,000. y తొలగిస్తే 3x = 15,000, కాబట్టి x = 5,000. P ఆదాయం ₹25,000. ఖర్చులు ₹21,000, ₹15,000 అవుతాయి.')
    for lang in ('en', 'te'):
        q['text'][lang] = q['text'][lang].replace('9,000', '4,000').replace('7,000', '5,000')
    ar(41, 'Missing correct option: 6 5/6 days.', 'Let total duration be t days. (t−2)/12 + (t−3)/15 + t/20 = 1. Multiply by 60: 5t−10 + 4t−12 + 3t = 60, so 12t = 82 and t = 41/6 = 6 5/6 days.', 'మొత్తం సమయం t రోజులు అనుకుందాం. (t−2)/12 + (t−3)/15 + t/20 = 1. 60తో గుణిస్తే 5t−10 + 4t−12 + 3t = 60. అందువల్ల 12t = 82; t = 41/6 = 6 5/6 రోజులు.', option=(1, '6 5/6 days', '6 5/6 రోజులు'))
    for n in (49, 50):
        q = lookup['arithmetic', n]
        q['text']['en'] = q['text']['en'].replace('Q | 1,500', 'R | 1,500')
        changes.append(('arithmetic', n, 'Correct duplicate English table label Q to R, matching Telugu and both solutions.'))

    def re(n, reason, en, te, **kwargs):
        return fix('reasoning', n, reason, en, te, **kwargs)

    q = re(3, 'No original arrangement. Change B to immediately right of D; answer becomes C (option A).', 'Facing the centre, left is clockwise and right is anticlockwise. Fix A first. The unique clockwise order is A, E, H, C, G, B, D, F. All revised clues hold, and C is immediately to H’s left.', 'కేంద్రం వైపు చూస్తున్నప్పుడు ఎడమవైపు అంటే సవ్యదిశ. A నుండి సవ్యదిశలో ఏకైక అమరిక A, E, H, C, G, B, D, F. సవరించిన అన్ని షరతులు సరిపోతాయి. H కి తక్షణ ఎడమవైపు C ఉన్నాడు.', option=(0, 'C', 'C'))
    q['text']['en'] = q['text']['en'].replace('B is sitting third to the right of D.', 'B is sitting immediately to the right of D.')
    q['text']['te'] = q['text']['te'].replace('D కి కుడివైపున మూడవ స్థానంలో B కూర్చున్నాడు.', 'D కి తక్షణ కుడివైపున B కూర్చున్నాడు.')
    q = re(5, 'Specify paternal grandfather to remove family-side ambiguity.', 'The paternal grandfather of Rajesh’s son is Rajesh’s father. His only daughter-in-law is Rajesh’s wife. Her only daughter is Rajesh’s daughter.', 'రాజేష్ కుమారుడి తండ్రి వైపు తాత అంటే రాజేష్ తండ్రి. ఆయన ఏకైక కోడలు రాజేష్ భార్య. ఆమె ఏకైక కుమార్తె రాజేష్ కుమార్తె.')
    q['text']['en'] = q['text']['en'].replace('the grandfather of my son', 'the paternal grandfather of my son')
    q['text']['te'] += '\nఇక్కడ తాత అంటే రాజేష్ కుమారుడి తండ్రి వైపు తాత.'
    q = re(10, 'Original stack impossible; require M and N to be adjacent.', 'From top to bottom the unique stack is K, N, M, L, J. K is immediately above N, M is not on top, L is below M and above J, and M and N are adjacent. Thus K is on top.', 'పై నుండి కిందకు ఏకైక అమరిక K, N, M, L, J. K వెంటనే N పైన ఉంది. M మొదట లేదు. L అనేది M కింద, J పైన ఉంది. M, N పక్కపక్కన ఉన్నాయి. పై పెట్టె K.')
    q['text']['en'] = q['text']['en'].replace('There are exactly two boxes between Box M and Box N.', 'Box M and Box N are adjacent, with no box between them.')
    q['text']['te'] = q['text']['te'].replace('Box', 'Box')
    q['text']['te'] = 'J, K, L, M, N అనే ఐదు పెట్టెలను ఒకదానిపై మరొకటి పేర్చారు. K వెంటనే N పైన ఉంది. L అనేది J పైన, M కింద ఉంది. M అన్నింటికంటే పైన లేదు. M మరియు N మధ్య మరే పెట్టె లేదు. అన్నింటికంటే పైన ఉన్న పెట్టె ఏది?'
    q = re(13, 'Original row impossible. R immediately left of P gives V third to right of R.', 'The unique left-to-right order is R, P, U, V, T, Q, S. P and Q have three persons between them. R is immediately left of P; S is immediately right of Q; one person is between S and T; V is immediately right of U. V is third to R’s right.', 'ఎడమ నుండి కుడికి ఏకైక వరుస R, P, U, V, T, Q, S. P, Q మధ్య ముగ్గురు; S, T మధ్య ఒక్కరు ఉన్నారు. R వెంటనే P ఎడమవైపు, V వెంటనే U కుడివైపు ఉన్నారు. V అనేది R కి కుడివైపు మూడవ స్థానంలో ఉన్నాడు.', answer=1)
    q['text']['en'] = q['text']['en'].replace('R sits second to the left of P.', 'R sits immediately to the left of P.')
    q['text']['te'] = 'P, Q, R, S, T, U, V ఉత్తరం వైపు చూస్తూ ఒక వరుసలో ఉన్నారు. P కి కుడివైపు ఉన్న Q కి P కి మధ్య సరిగ్గా ముగ్గురు ఉన్నారు. R వెంటనే P కి ఎడమవైపు ఉన్నాడు. S వెంటనే Q కి కుడివైపు ఉన్నాడు. S, T మధ్య ఒక్కరు ఉన్నారు. V వెంటనే U కి కుడివైపు ఉన్నాడు. R తో పోలిస్తే V ఏ స్థానంలో ఉన్నాడు?'
    q = re(14, 'Replace unsupported sequence with a consistent ×2+2 wrong-term question.', 'Each term should be twice the previous term plus 2: 6, 14, 30, 62, 126, 254. Thus 256 is the wrong term; it should be 254.', 'ప్రతి పదం ముందు పదానికి రెట్టింపు చేసి 2 కలిపితే రావాలి: 6, 14, 30, 62, 126, 254. కాబట్టి 256 తప్పు; దాని స్థానంలో 254 ఉండాలి.', text=('Find the wrong term in the series whose rule is “multiply by 2, then add 2”:\n6, 14, 30, 62, 126, 256', '“2తో గుణించి, 2 కలపడం” అనే నియమం పాటించే క్రింది శ్రేణిలో తప్పు పదాన్ని గుర్తించండి:\n6, 14, 30, 62, 126, 256'))
    q['options'] = {'en': ['14', '30', '62', '256'], 'te': ['14', '30', '62', '256']}
    re(15, 'State the set assumptions explicitly; police officers cannot form a disjoint set from all law-abiding citizens under those assumptions.', 'Under the stated assumptions, Police Officers is a subset of Law-abiding Citizens. Criminals is disjoint from Law-abiding Citizens and therefore also from Police Officers. One circle is inside another, with a third separate circle.', 'ఇచ్చిన ఊహల ప్రకారం పోలీసు అధికారులు చట్టాన్ని పాటించే పౌరుల ఉపసమితి. నేరస్తుల సమితి వాటితో కలవదు. కాబట్టి ఒక వృత్తం మరొక వృత్తం లోపల, మూడవ వృత్తం వేరుగా ఉంటుంది.', option=(2, 'One circle inside another, with a third disjoint circle', 'ఒక వృత్తం మరొకదానిలో ఉండి, మూడవ వృత్తం వేరుగా ఉండటం'), text=('For this question, assume all police officers are law-abiding citizens and no criminal is a law-abiding citizen. Which Venn-diagram relationship represents Police Officers, Criminals and Law-abiding Citizens?', 'ఈ ప్రశ్నలో పోలీసు అధికారులందరూ చట్టాన్ని పాటించే పౌరులని, ఏ నేరస్తుడూ చట్టాన్ని పాటించే పౌరుడు కాదని భావించండి. పోలీసు అధికారులు, నేరస్తులు, చట్టాన్ని పాటించే పౌరుల మధ్య సంబంధాన్ని ఏ వెన్ చిత్రం సూచిస్తుంది?'))
    re(17, 'North-East → North-West (40° west of north).', 'At 3:40, the minute hand is 240° and the hour hand 110° clockwise from 12. Rotating the clock so the minute hand points east (90°) puts the hour hand at 110−150 = −40° = 320°, i.e. 40° west of north.', '3:40కు నిమిషాల ముల్లు 240°, గంటల ముల్లు 110° వద్ద ఉంటాయి. నిమిషాల ముల్లు తూర్పు (90°) చూపేలా తిప్పితే గంటల ముల్లు 110−150 = −40° = 320° వద్ద ఉంటుంది. అంటే ఉత్తరం నుండి పశ్చిమానికి 40°, వాయవ్య దిశ.', option=(1, 'North-West (40° west of North)', 'వాయవ్యం (ఉత్తరం నుండి పశ్చిమానికి 40°)'))
