    re(27, 'Replace inconsistent first two columns with one common column rule.', 'In each column, bottom = top×middle − middle = middle×(top−1). Thus 6×(8−1)=42 and 5×(12−1)=55. Missing value = 7×(13−1) = 84.', 'ప్రతి నిలువు వరుసలో కింది సంఖ్య = మధ్య సంఖ్య × (పై సంఖ్య − 1). 6×(8−1)=42; 5×(12−1)=55. కావలసిన సంఖ్య = 7×(13−1)=84.', text=('Find the missing number. In every column, bottom = top × middle − middle.\n8    12    13\n6     5     7\n42   55     ?', 'ప్రతి నిలువు వరుసలో కింది సంఖ్య = పై సంఖ్య × మధ్య సంఖ్య − మధ్య సంఖ్య. తప్పిపోయిన సంఖ్య కనుగొనండి.\n8    12    13\n6     5     7\n42   55     ?'))
    re(28, 'Missing sixth letter M replaces K in option B.', 'REGULATION becomes Q,F,F,V,K,B,S,J,P,M. Sorted: B,F,F,J,K,M,P,Q,S,V. The sixth letter is M.', 'REGULATION మారిన తర్వాత Q,F,F,V,K,B,S,J,P,M వస్తాయి. అక్షర క్రమంలో B,F,F,J,K,M,P,Q,S,V. ఆరవ అక్షరం M.', option=(1, 'M', 'M'))
